<script setup lang="ts">
import { ref } from 'vue';
const account = ref(''); const password = ref(''); const error = ref(''); const loading = ref(false);
async function submit() { error.value = ''; loading.value = true; try { const response = await fetch(`${import.meta.env.VITE_API_BASE_URL || 'http://127.0.0.1:3000'}/api/auth/admin-login`, { method:'POST', headers:{'content-type':'application/json'}, body:JSON.stringify({ account:account.value, password:password.value }) }); if (!response.ok) throw new Error('账号或密码不正确'); const data = await response.json(); localStorage.setItem('admin-token', data.accessToken); localStorage.setItem('admin-profile', JSON.stringify(data.admin)); location.href = data.admin.role === 'SUPER_ADMIN' ? 'http://localhost:5176' : 'http://localhost:5175'; } catch (e) { error.value = e instanceof Error ? e.message : '登录失败'; } finally { loading.value = false; } }
</script>
<template><main class="login-page"><form class="login-card" @submit.prevent="submit"><div class="admin-logo" style="padding:0;color:#29213a"><span class="admin-logo-mark">✦</span>包小印 · 管理中心</div><h1>欢迎回来</h1><p>统一入口会依据管理员权限自动进入租户运营后台或平台总端。</p><label class="form-row">账号<input v-model="account" autocomplete="username" placeholder="请输入管理员账号"></label><label class="form-row">密码<input v-model="password" type="password" autocomplete="current-password" placeholder="请输入密码"></label><p v-if="error" style="color:#c34862;margin:-6px 0 16px">{{ error }}</p><button class="primary-btn" :disabled="loading">{{ loading ? '正在验证…' : '登录管理后台' }}</button></form></main></template>
